ORG_NAME = "Sankalp Utsav Samiti Mira Road"
ORG_ADDRESS = "Sankalp, 2 Poonam Sagar Complex, Mira Road East, Pincode 401107"
ORG_PAN = "PAN: ADAAS2976"

# Base64-embedded logo so the app is a single, portable file.
# (Generated once from the organization's logo image.)
LOGO_B64 = ""
STAMP_B64 = ""
# --------------------------------------------------------------------------
# Helpers
# --------------------------------------------------------------------------
def number_to_words_indian(number: int) -> str:
    """Convert an integer amount into words using the Indian numbering
    system (Lac / Crore), e.g. 380000 -> 'Three Lac Eighty Thousand'."""

    ones = [
        "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight",
        "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen",
        "Sixteen", "Seventeen", "Eighteen", "Nineteen",
    ]
    tens = [
        "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy",
        "Eighty", "Ninety",
    ]

    def two_digit(n):
        if n < 20:
            return ones[n]
        return (tens[n // 10] + (" " + ones[n % 10] if n % 10 else "")).strip()

    def three_digit(n):
        if n >= 100:
            return (ones[n // 100] + " Hundred" +
                    (" " + two_digit(n % 100) if n % 100 else "")).strip()
        return two_digit(n)

    if number == 0:
        return "Zero"

    crore = number // 10000000
    number %= 10000000
    lac = number // 100000
    number %= 100000
    thousand = number // 1000
    number %= 1000
    remainder = number

    parts = []
    if crore:
        parts.append(three_digit(crore) + " Crore")
    if lac:
        parts.append(three_digit(lac) + " Lac")
    if thousand:
        parts.append(three_digit(thousand) + " Thousand")
    if remainder:
        parts.append(three_digit(remainder))

    return " ".join(parts).strip()


def amount_in_words(amount: float) -> str:
    rupees = int(amount)
    paise = round((amount - rupees) * 100)
    words = "Rupees " + number_to_words_indian(rupees)
    if paise:
        words += " and " + number_to_words_indian(paise) + " Paise"
    words += " Only"
    return words


def get_logo_reader():
    """Return a BytesIO of the embedded logo, or None if not available."""
    if not LOGO_B64:
        return None
    try:
        return io.BytesIO(base64.b64decode(LOGO_B64))
    except Exception:
        return None


