def get_stamp_reader():
    """Return the signatory stamp image as a BytesIO object."""
    if not STAMP_B64:
        return None
    try:
        return io.BytesIO(base64.b64decode(STAMP_B64))
    except Exception:
        return None


def normalize_whatsapp_number(raw_number: str) -> str:
    """Convert a number to the digits needed for a WhatsApp URL."""
    if not raw_number:
        return ""
    digits = "".join(ch for ch in raw_number if ch.isdigit())
    if len(digits) >= 10:
        return digits
    return ""


# --------------------------------------------------------------------------
# PDF generation
# --------------------------------------------------------------------------
def build_receipt_pdf(donor_name, contact_no, address, receipt_no, receipt_date,
                       amount, payment_mode, purpose):
    buffer = io.BytesIO()
    page_w, page_h = A4
    margin = 15 * mm

    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        leftMargin=margin,
        rightMargin=margin,
        topMargin=margin,
        bottomMargin=margin,
    )

    styles = getSampleStyleSheet()
    org_name_style = ParagraphStyle(
        "OrgName", parent=styles["Title"], fontSize=18, leading=22,
        textColor=colors.HexColor("#8B0000"), alignment=TA_CENTER,
        spaceAfter=2,
    )
    org_address_style = ParagraphStyle(
        "OrgAddress", parent=styles["Normal"], fontSize=9.5, leading=13,
        alignment=TA_CENTER, textColor=colors.HexColor("#333333"),
    )
    receipt_title_style = ParagraphStyle(
        "ReceiptTitle", parent=styles["Heading2"], fontSize=13,
        alignment=TA_CENTER, textColor=colors.white, spaceAfter=0, spaceBefore=0,
    )
    label_style = ParagraphStyle(
        "Label", parent=styles["Normal"], fontSize=10, leading=14,
    )
    value_bold_style = ParagraphStyle(
        "ValueBold", parent=styles["Normal"], fontSize=10, leading=14,
        fontName="Helvetica-Bold",
    )
    footer_style = ParagraphStyle(
        "Footer", parent=styles["Normal"], fontSize=8, textColor=colors.grey,
    )

    story = []

    # ---- Header: logo + org name/address -------------------------------
    logo_reader = get_logo_reader()
    if logo_reader is not None:
        logo_img = RLImage(logo_reader, width=22 * mm, height=22 * mm)
        header_table = Table(
            [[logo_img,
              Paragraph(ORG_NAME, org_name_style)]],
            colWidths=[26 * mm, None],
        )
        header_table.setStyle(TableStyle([
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ALIGN", (1, 0), (1, 0), "CENTER"),
            ("LEFTPADDING", (0, 0), (0, 0), 0),
        ]))
        story.append(header_table)
    else:
        story.append(Paragraph(ORG_NAME, org_name_style))

    story.append(Paragraph(ORG_ADDRESS, org_address_style))
    story.append(Paragraph(f"<b>{ORG_PAN}</b>", org_address_style))
    story.append(Spacer(1, 8))

    # ---- "RECEIPT" banner -------------------------------------------------
    banner = Table([[Paragraph("RECEIPT", receipt_title_style)]],
                    colWidths=[doc.width])
    banner.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#8B0000")),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.append(banner)
    story.append(Spacer(1, 10))

    # ---- Donor details (left) + Receipt details (right) ------------------
    left_lines = [Paragraph(f"<b>Donor Name:</b> {donor_name}", label_style)]
    if address:
        left_lines.append(Paragraph(f"<b>Address:</b> {address}", label_style))
    if contact_no:
        left_lines.append(Paragraph(f"<b>Contact No:</b> {contact_no}", label_style))

    right_lines = [
        Paragraph(f"<b>Receipt No:</b> {receipt_no}", label_style),
        Paragraph(f"<b>Receipt Date:</b> {receipt_date.strftime('%d/%m/%Y')}", label_style),
        Paragraph(f"<b>Payment Mode:</b> {payment_mode}", label_style),
    ]

    details_table = Table(
        [[left_lines, right_lines]],
        colWidths=[doc.width * 0.55, doc.width * 0.45],
    )
    details_table.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("BOX", (0, 0), (-1, -1), 0.75, colors.HexColor("#8B0000")),
        ("INNERGRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#8B0000")),
        ("LEFTPADDING", (0, 0), (-1, -1), 8),
        ("RIGHTPADDING", (0, 0), (-1, -1), 8),
        ("TOPPADDING", (0, 0), (-1, -1), 8),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 8),
    ]))
    story.append(details_table)
    story.append(Spacer(1, 14))

    # ---- Amount table -------------------------------------------------
    amt_display = f"Rs. {amount:,.2f}"
    amount_table = Table(
        [
            ["Particulars", "Amount"],
            [purpose or "Donation", amt_display],
            ["Total Amount", amt_display],
        ],
        colWidths=[doc.width * 0.7, doc.width * 0.3],
    )
    amount_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#8B0000")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTNAME", (0, 2), (-1, 2), "Helvetica-Bold"),
        ("ALIGN", (1, 0), (1, -1), "RIGHT"),
        ("BOX", (0, 0), (-1, -1), 0.75, colors.HexColor("#8B0000")),
        ("INNERGRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#8B0000")),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
        ("LEFTPADDING", (0, 0), (-1, -1), 8),
        ("RIGHTPADDING", (0, 0), (-1, -1), 8),
    ]))
    story.append(amount_table)
    story.append(Spacer(1, 8))

    story.append(Paragraph(
        f"<b>Amount in Words:</b> {amount_in_words(amount)}", label_style))
    story.append(Spacer(1, 30))

    # ---- Thank-you note --------------------------------------------------
    story.append(Paragraph(
        "With grateful thanks for your generous contribution towards "
        f"{ORG_NAME}.", label_style))
    story.append(Spacer(1, 40))

    # ---- Signature line with stamped signatory -------------------------
    stamp_reader = get_stamp_reader()
    stamp_cell = []
    if stamp_reader is not None:
        stamp_cell = [RLImage(stamp_reader, width=24 * mm, height=24 * mm)]

    sign_table = Table(
        [[
            Paragraph("This is a system generated receipt.", footer_style),
            Table(
                [
                    stamp_cell,
                    [Paragraph(f"For, {ORG_NAME}", label_style)],
                    [Paragraph("Authorized Signatory", ParagraphStyle(
                        "AuthorizedSignatory",
                        parent=label_style,
                        alignment=TA_RIGHT,
                        fontName="Helvetica-Bold",
                        fontSize=10,
                    ))],
                ],
                colWidths=[70 * mm],
                style=TableStyle([
                    ("ALIGN", (0, 0), (0, 0), "CENTER"),
                ]),
            ),
        ]],
        colWidths=[doc.width * 0.45, doc.width * 0.55],
    )
    sign_table.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "BOTTOM"),
        ("ALIGN", (1, 0), (1, 0), "RIGHT"),
        ("LEFTPADDING", (1, 0), (1, 0), 30),
    ]))
    story.append(sign_table)

    def add_page_border(canvas, doc_obj):
        margin_border = 8 * mm
        canvas.saveState()
        canvas.setStrokeColor(colors.HexColor("#B22222"))
        canvas.setLineWidth(2)
        canvas.rect(
            margin_border,
            margin_border,
            page_w - (2 * margin_border),
            page_h - (2 * margin_border),
            stroke=1,
            fill=0,
        )
        canvas.restoreState()

    doc.build(story, onFirstPage=add_page_border, onLaterPages=add_page_border)
    buffer.seek(0)
    return buffer


# --------------------------------------------------------------------------
# Streamlit UI
# --------------------------------------------------------------------------
st.set_page_config(page_title="Sankalp Utsav Samiti - Receipt Generator", page_icon="🧾")

st.title("🧾 Donation Receipt Generator")
st.caption(f"{ORG_NAME} — {ORG_ADDRESS}")

logo_reader = get_logo_reader()
if logo_reader is not None:
    st.image(logo_reader, width=90)

with st.form("receipt_form"):
    st.subheader("Donor & Receipt Details")

    col1, col2 = st.columns(2)
    with col1:
        donor_name = st.text_input("Donor Name ", placeholder="e.g. Mr. Ramesh Kumar Shah")
        contact_no = st.text_input("Contact Number", placeholder="e.g. +91-9876543210")
        receipt_no = st.text_input("Receipt Number ", placeholder="e.g. SUS/2026/001")
    with col2:
        address = st.text_input("Donor Address (optional)")
        receipt_date = st.date_input("Receipt Date ", value=date.today())
        payment_mode = st.selectbox(
            "Payment Mode", ["","Cash", "Cheque", "Online Transfer / UPI", "Card", "Other"]
        )

    amount = st.number_input("Amount Donated (₹) ", step=100.0, format="%.2f")
    purpose = st.text_input("Purpose (optional)", value="Donation")

    submitted = st.form_submit_button("Generate Receipt PDF", type="primary")

if submitted:
    if not donor_name.strip():
        st.error("Please enter the donor's name.")
    elif not receipt_no.strip():
        st.error("Please enter a receipt number.")
    elif amount <= 0:
        st.error("Please enter an amount greater than zero.")
    else:
        pdf_buffer = build_receipt_pdf(
            donor_name=donor_name.strip(),
            contact_no=contact_no.strip(),
            address=address.strip(),
            receipt_no=receipt_no.strip(),
            receipt_date=receipt_date,
            amount=amount,
            payment_mode=payment_mode,
            purpose=purpose.strip(),
        )
        st.success("Receipt generated successfully!")
        file_name = f"Receipt_{receipt_no.strip().replace('/', '-')}.pdf"
        pdf_b64 = base64.b64encode(pdf_buffer.getvalue()).decode("ascii")
        phone_number = normalize_whatsapp_number(contact_no.strip())

        whatsapp_html = f"""
        <div style="display:flex; justify-content:flex-start; margin-top: 12px;">
            <button id="whatsapp-share-btn" style="
                background: #25D366; color: white; border: none; border-radius: 8px;
                padding: 10px 18px; font-size: 15px; font-weight: 600; cursor: pointer;
                box-shadow: 0 2px 8px rgba(0,0,0,0.15);">
                💬 Share Receipt on WhatsApp
            </button>
        </div>
        <script>
            const pdfData = "data:application/pdf;base64,{pdf_b64}";
            const donorPhone = "{phone_number}";

            async function shareReceiptToWhatsApp() {{
                try {{
                    const base64 = pdfData.split(",")[1];
                    const binary = atob(base64);
                    const len = binary.length;
                    const bytes = new Uint8Array(len);
                    for (let i = 0; i < len; i++) {{
                        bytes[i] = binary.charCodeAt(i);
                    }}
                    const file = new File([bytes.buffer], "{file_name}", {{ type: "application/pdf" }});
                    if (navigator.share && navigator.canShare && navigator.canShare({{ files: [file] }})) {{
                        await navigator.share({{
                            title: "Donation Receipt",
                            text: "Please find the donation receipt.",
                            files: [file],
                        }});
                        return;
                    }}
                }} catch (error) {{
                    console.log("Share sheet unavailable:", error);
                }}

                const text = encodeURIComponent("Please find the donation receipt.");
                const waUrl = donorPhone
                    ? `https://wa.me/${{donorPhone}}?text=${{text}}`
                    : `https://wa.me/?text=${{text}}`;
                window.open(waUrl, "_blank");
            }}

            document.getElementById("whatsapp-share-btn").addEventListener("click", shareReceiptToWhatsApp);
        </script>
        """
        st.components.v1.html(whatsapp_html, height=110)
